--[=[
    @class PropertyItem

    * 属性物品
    * 属性物品为特殊的元素, 其包含一个属性容器, 用于存放属性

    注意: 属性物品是 Element 子类, 继承所有 Element 成员
]=]
local PropertyItem = {}
local Element = require(script.Parent.Element)
local ElementContainer = require(script.Parent.ElementContainer)

export type Type = typeof(PropertyItem) & Element.Type

local propertyContainer: ElementContainer.Type = nil

--- @prop PropertyContainer Container
--- @within PropertyItem
--- 属性容器
PropertyItem.PropertyContainer = propertyContainer

return PropertyItem
